INSERT INTO students (first_name, last_name, email, major)
VALUES (?, ?, ?, ?);
UPDATE students
SET first_name = ?, last_name = ?, email = ?, major = ?
WHERE student_id = ?;

INSERT INTO courses (department_id, course_code, title, credits)
VALUES (?, ?, ?, ?);
UPDATE courses
SET department_id = ?, course_code = ?, title = ?, credits = ?
WHERE course_id = ?;
